let container = Container()
container.register(OrderRepository.self) { r in
    SqlOrderRepository(pool: r.resolve(Pool.self)!)
}
container.register(OrderService.self) { r in
    OrderService(repo: r.resolve(OrderRepository.self)!)
}.inObjectScope(.container)

let service = container.resolve(OrderService.self)!

extension Container {
    var repo: Factory<OrderRepository> {
        self { SqlOrderRepository(pool: Container.shared.pool()) }
    }
    var service: Factory<OrderService> {
        self { OrderService(repo: self.repo()) }
    }
}

